from glyph import parse, evaluate, S, K, I, App

M = App(App(S,I),I)  # SII, the self-application combinator
# Try X = I, Y = M: App(I, M) settles to M (already NF). App(M, I) = SII I -> I I -> I. also settles.
# Try X = K I, Y = M: App(KI, M) -> I (settles). App(M, KI) = SII (KI) -> (I(KI))(I(KI)) -> (KI)(KI) -> I. settles too.

# We actually need M M to diverge, i.e. X=M,Y=M (symmetric - disallowed as no-op).
# Alternative: use a different single-site rewrite target deeper in tree so pre != post syntactically
# even though the *effective loop* still needs M applied to M somewhere down chain.

# Try nested: pre = App(App(K, Z), M) where swap acts on the INNER App(K,Z) turning into App(Z,K)... 
# Let's just search programmatically over small pre terms with one App swap producing divergence.
import itertools

atoms = {"I": I, "K": K, "S": S}
def small_terms(depth):
    if depth == 0:
        for name, t in atoms.items():
            yield t
    else:
        for a in small_terms(0):
            for b in small_terms(depth-1):
                yield App(a,b)
                yield App(b,a)

candidates = list(small_terms(1)) + list(small_terms(2))
found = []
for pre in candidates:
    if not isinstance(pre, App):
        continue
    swapped = App(pre.right, pre.left)
    if swapped == pre:
        continue
    try:
        res_pre = evaluate(pre, max_atp=300)
        res_post = evaluate(swapped, max_atp=300)
    except Exception:
        continue
    if res_pre.is_settled() and not res_post.is_settled():
        found.append((pre, swapped))

for f in found[:10]:
    print(f[0], "->", f[1])
print(len(found))
EOF
